(94123, 'ruRU', '|TInterface\\Icons\\INV_Bijou_purple.blp:20|t|cFFFF0000|Hspell:181365|h[Бурная реакция]|h|r происходит от прыжка Кормрока в Теневой пруд!', '', 24330),
(94124, 'ruRU', '|TInterface\\Icons\\INV_Bijou_orange.blp:20|t|cFFFF0000|Hspell:181370|h[Бурная реакция]|h|r происходит от прыжка Кормрока в Огненный пруд!', '', 24330),
(94125, 'ruRU', '|TInterface\\Icons\\INV_Bijou_green.blp:20|t|cFFFF0000|Hspell:181371|h[Бурная реакция]|h|r происходит от прыжка Кормрока в Мерзкий пруд!', '', 24330),
(94126, 'ruRU', '|TInterface\\Icons\\spell_fire_rune.blp:20|t$n активирует |cFFFF0000|Hspell:180370|h[Взрывную руну]|h|r.', '', 24330),
(94127, 'ruRU', '|TInterface\\Icons\\spell_fire_rune.blp:20|t|cFFFF0000|Hspell:180370|h[Взрывная руна]|h|r взрывается сама по себе.', '', 24330),
(94128, 'ruRU', '|TInterface\\Icons\\Trade_Engineering.blp:20|t|cFFFF0000|Hspell:181300|h[Усиленная Рука Скверны]|h|r |cFFFF0000|Hspell:180442|h[Высвобождает]|h|r смертоносный всплеск энергии Скверны!', '', 24330),
(94129, 'ruRU', 'Он не... архидруид... спасайся... беги!', '', 24330),
(94132, 'ruRU', '[Таттерсейл рассказывает вам всё, что знает, и убегает.]', '', 24330),
(94133, 'ruRU', 'Я не умру снова без боя!', '', 24330),
(94134, 'ruRU', 'На этот раз тебе не скормить меня гончим!', '', 24330),
(94135, 'ruRU', 'Хелира! Ты не удержишь меня здесь вечно! Я буду свободен!', '', 24330),
(94136, 'ruRU', 'Это прекрасное безумие... зачем я сопротивлялся ему?', '', 24330),
(94137, 'ruRU', '%s выбирает вас целью для |cFFFF0404|Hspell:180372|h[Искателя сердец]|h|r!', '', 24330),
(94138, 'ruRU', 'Спрятаться негде.', '', 24330),
(94139, 'ruRU', 'Что-то привело фурболгов в неистовство. На моей памяти они никогда не нападали такими силами.', '', 24330),
(94140, 'ruRU', 'Сердце друида Когтя никогда не дрогнет. Мы те, кто выстоит.', '', 24330),
(94141, 'ruRU', 'Архидруид Стальной Коготь всё ещё там, в курганах, вместе с остальными. Нужно спасти их как можно скорее.', '', 24330);
